(7063199, 1074684, 30982, '<td valign="top">Oooh - wonderful textures and designs formed by the condensation!  Nice choice!</td>', 'Oooh - wonderful textures and designs formed by the condensation!  Nice choice!', '2013-07-10 00:36:43.000000', NULL, 1),
