(7063202, 1074549, 30982, '<td valign="top">The branching is quite fascinating - nice color, too.  A microwaved disk?</td>', 'The branching is quite fascinating - nice color, too.  A microwaved disk?', '2013-07-10 00:41:21.000000', NULL, 1),
(7063203, 1074807, 30982, '<td valign="top">Ha!  Either a very young dog or one with a very good dentist!  Fun shot!</td>', 'Ha!  Either a very young dog or one with a very good dentist!  Fun shot!', '2013-07-10 00:41:44.000000', NULL, 1),
(7063204, 1074758, 30982, '<td valign="top">Nice interpretation of the challenge!</td>', 'Nice interpretation of the challenge!', '2013-07-10 00:41:58.000000', NULL, 1),
(7063205, 1074625, 30982, '<td valign="top">Indeed - a tiny crystal ball for the faeries to use!</td>', 'Indeed - a tiny crystal ball for the faeries to use!', '2013-07-10 00:42:21.000000', NULL, 1),
(7063206, 1074805, 30982, '<td valign="top">Such a lovely background to show off the dewdrop.</td>', 'Such a lovely background to show off the dewdrop.', '2013-07-10 00:42:41.000000', NULL, 1),
(7063207, 1074806, 30982, '<td valign="top">Stark and harsh - probably the way the leaf feels after being frozen!</td>', 'Stark and harsh - probably the way the leaf feels after being frozen!', '2013-07-10 00:43:04.000000', NULL, 1),
(7063208, 1074287, 30982, '<td valign="top">An interesting angle for a water drop shot - the formed figures are well described by your title.  I also like the tiny droplet floating to the left.</td>', 'An interesting angle for a water drop shot - the formed figures are well described by your title.  I also like the tiny droplet floating to the left.', '2013-07-10 00:43:42.000000', NULL, 1),
