(7063735, 1074758, 114225, '<td valign="top">Great subject, with so many little droplets. But I''m not fond of the darkness that feels artificial.</td>', 'Great subject, with so many little droplets. But I''m not fond of the darkness that feels artificial.', '2013-07-10 09:12:00.000000', NULL, 1),
(7063737, 1074311, 114225, '<td valign="top">Very classic lighting style.</td>', 'Very classic lighting style.', '2013-07-10 09:12:17.000000', NULL, 1),
(7063738, 1074549, 114225, '<td valign="top">That is great. It almost appears  light the branch is extending into the drop.</td>', 'That is great. It almost appears  light the branch is extending into the drop.', '2013-07-10 09:13:08.000000', NULL, 1),
(7063740, 1074509, 114225, '<td valign="top">Well done! Great subject, and use of the style of photo. I do wish the exposure was turned up a bit.</td>', 'Well done! Great subject, and use of the style of photo. I do wish the exposure was turned up a bit.', '2013-07-10 09:13:44.000000', NULL, 1),
(7063743, 1074630, 114225, '<td valign="top">Heh, that is a cute idea. Could be a bit sharper to really look great.</td>', 'Heh, that is a cute idea. Could be a bit sharper to really look great.', '2013-07-10 09:14:33.000000', NULL, 1),
(7063746, 1074824, 114225, '<td valign="top">Nice. I love the message and light.</td>', 'Nice. I love the message and light.', '2013-07-10 09:15:36.000000', NULL, 1),
